  real_T wp[2];
  real_T bigNum;
  int32_T U_size[2];
  int32_T bigNum_size[2];
  int32_T vec_size[2];
  int32_T x_size[2];
  int32_T y_size[2];
  int32_T b_i;
  int32_T i;
  int32_T i1;
  int32_T j;
  int32_T nz;
  int32_T trueCount;
  char_T b_u[40];
  char_T u[39];
  int8_T d_tmp_data[2];
  int8_T tmp_data[2];
  boolean_T isBehind[2];
  boolean_T b_isBehind;
  st.prev = sp;
