    b_bsxfun(t73_Intrinsics_ImageSize, vec_data, U_size, x_data, x_size);
    vec_size[0] = 2;
    vec_size[1] = x_size[1];
    j = x_size[0] * x_size[1];
    if (j - 1 >= 0) {
      memcpy(&vec_data[0], &x_data[0], (uint32_T)j * sizeof(real_T));
    }

    power(vec_data, vec_size, x_data, x_size);
    if (x_size[1] == 0) {
      y_size[0] = 1;
      y_size[1] = 0;
    } else {
      y_size[0] = 1;
      y_size[1] = (int8_T)x_size[1];
      i = x_size[1] - 1;
      for (b_i = 0; b_i <= i; b_i++) {
        y_data[b_i] = b_sumColumnB(x_data, b_i + 1);
      }
    }

    st.site = &qd_emlrtRSI;
    b_sqrt(&st, y_data, y_size, b_tmp_data, U_size);
    j = U_size[0] * U_size[1];
    if (j - 1 >= 0) {
      memcpy(&c_tmp_data[0], &b_tmp_data[0], (uint32_T)j * sizeof(real_T));
    }

    st.site = &td_emlrtRSI;
    b_st.site = &vd_emlrtRSI;
    assertValidSizeArg(&b_st, (real_T)nz);
    j = 1;
    if (U_size[1] > 1) {
      j = 2;
    }

    if (nz > muIntScalarMax_sint32(U_size[1], j)) {
      for (i = 0; i < 39; i++) {
        u[i] = c_u[i];
      }

      y = NULL;
      m = emlrtCreateCharArray(2, &iv1[0]);
      emlrtInitCharArrayR2013a((emlrtConstCTX)sp, 39, m, &u[0]);
      emlrtAssign(&y, m);
      for (i = 0; i < 39; i++) {
        u[i] = c_u[i];
      }

      c_y = NULL;
      m = emlrtCreateCharArray(2, &iv3[0]);
      emlrtInitCharArrayR2013a((emlrtConstCTX)sp, 39, m, &u[0]);
      emlrtAssign(&c_y, m);
      st.site = &wq_emlrtRSI;
      error(&st, y, getString(&st, b_message(&st, c_y, &o_emlrtMCI), &o_emlrtMCI),
            &o_emlrtMCI);
    }

    if (nz != U_size[1]) {
      for (i = 0; i < 40; i++) {
        b_u[i] = d_u[i];
      }

      b_y = NULL;
      m = emlrtCreateCharArray(2, &iv2[0]);
      emlrtInitCharArrayR2013a((emlrtConstCTX)sp, 40, m, &b_u[0]);
      emlrtAssign(&b_y, m);
      for (i = 0; i < 40; i++) {
        b_u[i] = d_u[i];
      }

      d_y = NULL;
      m = emlrtCreateCharArray(2, &iv4[0]);
      emlrtInitCharArrayR2013a((emlrtConstCTX)sp, 40, m, &b_u[0]);
      emlrtAssign(&d_y, m);
      st.site = &ar_emlrtRSI;
      error(&st, b_y, getString(&st, b_message(&st, d_y, &q_emlrtMCI),
             &q_emlrtMCI), &q_emlrtMCI);
    }

    U_size[0] = 1;
    U_size[1] = nz;
    st.site = &rd_emlrtRSI;
    c_bsxfun(&st, vec_data, vec_size, c_tmp_data, U_size, x_data, x_size);
    vec_size[0] = 2;
    vec_size[1] = x_size[1];
    j = x_size[0] * x_size[1];
    if (j - 1 >= 0) {
      memcpy(&vec_data[0], &x_data[0], (uint32_T)j * sizeof(real_T));
    }

    trueCount = 0;
    j = 0;
