static void visionDetectionGenerator_isAbove(visionDetectionGenerator *obj,
  real_T pts[200], real_T r0[2], boolean_T flag[100])
{
  real_T b_pts[200];
  real_T dv[200];
  real_T b_vUp[100];
  real_T b_r0[2];
  real_T vUp[2];
  int32_T b_i;
  int32_T i;
  int32_T i1;
  for (i = 0; i < 2; i++) {
    vUp[i] = obj->puvUp[i];
  }

  memcpy(&b_pts[0], &pts[0], 200U * sizeof(real_T));
  for (b_i = 0; b_i < 2; b_i++) {
    b_r0[b_i] = r0[b_i];
  }

  f_bsxfun(b_pts, b_r0, dv);
  for (i = 0; i < 100; i++) {
    b_vUp[i] = 0.0;
    for (i1 = 0; i1 < 2; i1++) {
      b_vUp[i] += vUp[i1] * dv[i1 + (i << 1)];
    }

    flag[i] = (muDoubleScalarRound(b_vUp[i] * 1.0E+6) > 0.0);
  }
}

static void f_bsxfun(real_T a[200], real_T b[2], real_T c[200])
{
  __m128d r;
  __m128d r1;
  int32_T b_k;
  int32_T k;
  for (k = 0; k < 100; k++) {
    for (b_k = 0; b_k <= 0; b_k += 2) {
      r = _mm_loadu_pd(&a[k << 1]);
      r1 = _mm_loadu_pd(&b[0]);
      _mm_storeu_pd(&c[k << 1], _mm_sub_pd(r, r1));
    }
  }
}

static int32_T combineVectorElements(boolean_T x[100])
{
  int32_T k;
  int32_T y;
  y = (int32_T)x[0];
  for (k = 0; k < 99; k++) {
    y += (int32_T)x[k + 1];
  }

  return y;
}

