  st.site = &qj_emlrtRSI;
  AbstractDetectionGenerator_egoToSensor(&st, c_x_data, b_x_size, xSen_data,
    xSen_size);
  nx = 72 * facesEgo_size[3];
  st.site = &td_emlrtRSI;
