  int32_T i1;
  int32_T i2;
  int32_T i3;
  int32_T k;
  int32_T m;
  st.prev = sp;
  st.tls = sp->tls;
  for (i = 0; i < 7; i++) {
    actorProfiles[i] = obj->pActorProfiles[i];
  }

  st.site = &sj_emlrtRSI;
  AbstractDetectionGenerator_concatFieldValues(&st, actors_data, actors_size,
    actorIDs_data, actorIDs_size);
  i = actors_size[0] - 1;
  faces_size[0] = 3;
  faces_size[1] = 4;
