static void AbstractDetectionGenerator_isSensorInsideActor(const emlrtStack *sp,
  real_T facesSen_data[], int32_T facesSen_size[4], boolean_T *isInsideAny,
  emxArray_real_T *actorIdx)
{
  real_T thisCube[72];
  real_T b_thisCube[12];
  real_T b_y1[9];
  real_T vp[3];
  real_T t;
  real_T tmp1;
  real_T work;
  real_T y;
  int32_T b_s;
  int32_T i;
  int32_T iActor;
  int32_T iFace;
  int32_T ix;
  int32_T ixLead;
  int32_T iy;
  int32_T iyLead;
  int32_T m;
  boolean_T b_isInsideAny;
  boolean_T exitg1;
  boolean_T isInsideActor;
  actorIdx->size[0] = 1;
  actorIdx->size[1] = 0;
  b_isInsideAny = false;
  i = facesSen_size[3] - 1;
  for (iActor = 0; iActor <= i; iActor++) {
    isInsideActor = true;
    ix = emlrtDynamicBoundsCheckR2012b(iActor + 1, 1, facesSen_size[3],
      &cd_emlrtBCI, (emlrtConstCTX)sp);
    for (ixLead = 0; ixLead < 6; ixLead++) {
      for (iyLead = 0; iyLead < 4; iyLead++) {
        for (iy = 0; iy < 3; iy++) {
          thisCube[(iy + 3 * iyLead) + 12 * ixLead] = facesSen_data[((iy + 3 *
            iyLead) + 12 * ixLead) + 72 * (ix - 1)];
        }
      }
    }

    iFace = 0;
    exitg1 = false;
    while ((!exitg1) && (iFace < 6)) {
      ix = 0;
      iy = 1;
      for (b_s = 0; b_s < 3; b_s++) {
        ixLead = ix + 3;
        iyLead = iy - 1;
        work = thisCube[(ix % 3 + 3 * div_nzp_s32_floor(ix, 3)) + 12 * iFace];
        for (m = 0; m < 3; m++) {
          tmp1 = work;
          work = thisCube[(ixLead % 3 + 3 * div_nzp_s32_floor(ixLead, 3)) + 12 *
            iFace];
          tmp1 = thisCube[(ixLead % 3 + 3 * div_nzp_s32_floor(ixLead, 3)) + 12 *
            iFace] - tmp1;
          ixLead += 3;
          b_y1[iyLead] = tmp1;
          iyLead += 3;
        }

        ix++;
        iy++;
      }

      vp[0] = b_y1[1] * b_y1[5] - b_y1[2] * b_y1[4];
      vp[1] = b_y1[2] * b_y1[3] - b_y1[0] * b_y1[5];
      vp[2] = b_y1[0] * b_y1[4] - b_y1[1] * b_y1[3];
      y = 0.0;
      tmp1 = 3.3121686421112381E-170;
      for (ix = 0; ix < 3; ix++) {
        work = muDoubleScalarAbs(vp[ix]);
        if (work > tmp1) {
          t = tmp1 / work;
          y = y * t * t + 1.0;
          tmp1 = work;
        } else {
          t = work / tmp1;
          y += t * t;
        }
      }

      y = tmp1 * muDoubleScalarSqrt(y);
      for (ixLead = 0; ixLead < 4; ixLead++) {
        for (iyLead = 0; iyLead < 3; iyLead++) {
          b_thisCube[iyLead + 3 * ixLead] = thisCube[(iyLead + 3 * ixLead) + 12 *
            iFace];
        }
      }

      tmp1 = 0.0;
      for (ixLead = 0; ixLead < 3; ixLead++) {
        tmp1 += b_thisCube[ixLead] * (vp[ixLead] / y);
      }

      isInsideActor = (tmp1 > 0.0);
      if (!isInsideActor) {
        exitg1 = true;
      } else {
        iFace++;
      }
    }

    if (isInsideActor) {
      ixLead = actorIdx->size[1];
      iyLead = actorIdx->size[0] * actorIdx->size[1];
      actorIdx->size[0] = 1;
      actorIdx->size[1]++;
      emxEnsureCapacity_real_T(actorIdx, iyLead);
      actorIdx->data[ixLead] = (real_T)iActor + 1.0;
    }

    if (b_isInsideAny || isInsideActor) {
      b_isInsideAny = true;
    } else {
      b_isInsideAny = false;
    }
  }

  *isInsideAny = b_isInsideAny;
}

