static void backfaceCull(const emlrtStack *sp, real_T polys_data[], int32_T
  polys_size[4], real_T vispolys_data[], int32_T vispolys_size[4])
{
  emlrtStack st;
  int32_T isFacing_size[2];
  int32_T b_i;
  int32_T i;
  int32_T loop_ub;
  int32_T partialTrueCount;
  int32_T trueCount;
  int8_T tmp_data[36];
  boolean_T isFacing_data[36];
  boolean_T b_isFacing_data;
  st.prev = sp;
  st.tls = sp->tls;
  vispolys_size[0] = 3;
  vispolys_size[1] = 4;
  vispolys_size[2] = 6;
  vispolys_size[3] = polys_size[3];
  loop_ub = 72 * polys_size[3];
  if (loop_ub - 1 >= 0) {
    memcpy(&vispolys_data[0], &polys_data[0], (uint32_T)loop_ub * sizeof(real_T));
  }

  st.site = &ak_emlrtRSI;
  isFacing(&st, polys_data, polys_size, isFacing_data, isFacing_size);
  loop_ub = 6 * isFacing_size[1] - 1;
  trueCount = 0;
  partialTrueCount = 0;
  for (i = 0; i <= loop_ub; i++) {
    b_isFacing_data = isFacing_data[i];
    if (!b_isFacing_data) {
      trueCount++;
      tmp_data[partialTrueCount] = (int8_T)i;
      partialTrueCount++;
    }
  }

  loop_ub = 6 * polys_size[3];
  for (partialTrueCount = 0; partialTrueCount < trueCount; partialTrueCount++) {
    for (i = 0; i < 4; i++) {
      for (b_i = 0; b_i < 3; b_i++) {
        vispolys_data[(b_i + 3 * i) + 12 * emlrtDynamicBoundsCheckR2012b
          ((int32_T)tmp_data[partialTrueCount], 0, loop_ub - 1, &sd_emlrtBCI,
           (emlrtConstCTX)sp)] = rtNaN;
      }
    }
  }
}

