static void c_sqrt(real_T x_data[], int32_T x_size[3], real_T b_x_data[],
                   int32_T b_x_size[3])
{
  __m128d r;
  real_T c_x_data;
  int32_T k;
  int32_T loop_ub;
  int32_T scalarLB;
  int32_T vectorUB;
  b_x_size[1] = x_size[1];
  b_x_size[2] = x_size[2];
  loop_ub = x_size[1] * x_size[2];
  if (loop_ub - 1 >= 0) {
    memcpy(&b_x_data[0], &x_data[0], (uint32_T)loop_ub * sizeof(real_T));
  }

  b_x_size[0] = 1;
  loop_ub = x_size[1] * x_size[2] - 1;
  scalarLB = (loop_ub + 1) / 2 * 2;
  vectorUB = scalarLB - 2;
  for (k = 0; k <= vectorUB; k += 2) {
    r = _mm_loadu_pd(&b_x_data[k]);
    _mm_storeu_pd(&b_x_data[k], _mm_sqrt_pd(r));
  }

  for (k = scalarLB; k <= loop_ub; k++) {
    c_x_data = b_x_data[k];
    c_x_data = muDoubleScalarSqrt(c_x_data);
    b_x_data[k] = c_x_data;
  }
}

