static real_T polyarea(const emlrtStack *sp, emxArray_real_T *x, emxArray_real_T
  *y)
{
  static const int32_T iv[2] = { 1, 30 };

  static const int32_T iv1[2] = { 1, 30 };

  static char_T b_u[30] = { 'M', 'A', 'T', 'L', 'A', 'B', ':', 'p', 'o', 'l',
    'y', 'a', 'r', 'e', 'a', ':', 'X', 'Y', 'S', 'i', 'z', 'e', 'M', 'i', 's',
    'm', 'a', 't', 'c', 'h' };

  emlrtStack st;
  const mxArray *c_y;
  const mxArray *d_y;
  const mxArray *m;
  real_T b_x[2];
  real_T b_y[2];
  real_T area;
  real_T b_s;
  int32_T i;
  int32_T k;
  char_T u[30];
  st.prev = sp;
  st.tls = sp->tls;
  for (i = 0; i < 2; i++) {
    b_x[i] = (real_T)x->size[i];
    b_y[i] = (real_T)y->size[i];
  }

  if (!isequal(b_x, b_y)) {
    for (i = 0; i < 30; i++) {
      u[i] = b_u[i];
    }

    c_y = NULL;
    m = emlrtCreateCharArray(2, &iv[0]);
    emlrtInitCharArrayR2013a((emlrtConstCTX)sp, 30, m, &u[0]);
    emlrtAssign(&c_y, m);
    for (i = 0; i < 30; i++) {
      u[i] = b_u[i];
    }

    d_y = NULL;
    m = emlrtCreateCharArray(2, &iv1[0]);
    emlrtInitCharArrayR2013a((emlrtConstCTX)sp, 30, m, &u[0]);
    emlrtAssign(&d_y, m);
    st.site = &qr_emlrtRSI;
    error(&st, c_y, getString(&st, b_message(&st, d_y, &gc_emlrtMCI),
           &gc_emlrtMCI), &gc_emlrtMCI);
  }

  if (x->size[1] == 0) {
    area = 0.0;
  } else {
    b_s = (x->data[0] - x->data[x->size[1] - 1]) * (y->data[0] + y->data[x->
      size[1] - 1]) / 2.0;
    i = x->size[1] - 2;
    for (k = 0; k <= i; k++) {
      b_s += (x->data[k + 1] - x->data[k]) * (y->data[k + 1] + y->data[k]) / 2.0;
    }

    area = muDoubleScalarAbs(b_s);
  }

  return area;
}

